const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function MonthYearPicker({ value, onChange, placeholder = '----------, ----' }: { value: string; onChange: (v: string) => void; placeholder?: string }) {
  const [open, setOpen] = useState(false);
  const [viewYear, setViewYear] = useState(() => (value ? Number(value.split('-')[0]) : new Date().getFullYear()));
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const selectedMonthIdx = value ? Number(value.split('-')[1]) - 1 : -1;
  const selectedYear = value ? Number(value.split('-')[0]) : null;
  const display = value ? `${MONTHS[selectedMonthIdx]}, ${selectedYear}` : placeholder;

  const pick = (monthIdx: number) => {
    const mm = String(monthIdx + 1).padStart(2, '0');
    onChange(`${viewYear}-${mm}`);
    setOpen(false);
  };

  const thisMonth = () => {
    const now = new Date();
    setViewYear(now.getFullYear());
    onChange(`${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`);
    setOpen(false);
  };

  return (
    <div className="relative" ref={ref}>
      <button type="button" className="input text-left w-full" onClick={() => setOpen(o => !o)}>
        <span className={value ? '' : 'text-slate-400'}>{display}</span>
      </button>

      {open && (
        <div className="absolute z-20 mt-1 w-64 bg-white border border-slate-200 rounded-lg shadow-lg p-3">
          <div className="flex items-center justify-between bg-slate-100 rounded px-2 py-1.5 mb-3">
            <button type="button" className="px-2 text-slate-500 hover:text-slate-800" onClick={() => setViewYear(y => y - 1)}>‹</button>
            <span className="font-medium text-slate-700">{viewYear}</span>
            <button type="button" className="px-2 text-slate-500 hover:text-slate-800" onClick={() => setViewYear(y => y + 1)}>›</button>
          </div>

          <div className="grid grid-cols-4 gap-2 mb-3">
            {MONTHS.map((m, idx) => {
              const isSelected = selectedYear === viewYear && selectedMonthIdx === idx;
              return (
                <button
                  key={m}
                  type="button"
                  onClick={() => pick(idx)}
                  className={`text-sm py-1.5 rounded-md ${
                    isSelected ? 'bg-blue-600 text-white font-semibold' : 'text-slate-700 hover:bg-slate-100'
                  }`}
                >
                  {m}
                </button>
              );
            })}
          </div>

          <div className="flex items-center justify-between text-xs">
            <button type="button" className="text-blue-600 hover:underline" onClick={() => onChange('')}>Clear</button>
            <button type="button" className="text-blue-600 hover:underline" onClick={thisMonth}>This month</button>
          </div>
        </div>
      )}
    </div>
  );
}


const COLORS = ['#1B4FD8', '#10B981', '#F59E0B', '#EF4444', '#8B5CF6', '#06B6D4', '#F97316'];

export function ConnectorDashboard() {
  const [stats, setStats] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => { dashAPI.getStats().then(r => setStats(r.data)).finally(() => setLoading(false)); }, []);

  if (loading) return <LoadingSpinner fullPage />;

  const pieData = Object.entries(stats?.loanTypeBreakdown || {}).map(([name, value]) => ({ name, value }));

  return (
    <div>
      <PageHeader title="My Dashboard" breadcrumbs={['Connector', 'Dashboard']}
        actions={<button className="btn-primary flex items-center gap-2 text-sm" onClick={() => navigate('/connector/applications/new')}><FiPlus /> New Application</button>} />

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        <StatCard title="Total Applications" value={stats?.totalApplications || 0} icon={<FiFileText />} color="text-primary bg-primary-50" />
        <StatCard title="Pending" value={stats?.pendingApplications || 0} icon={<FiFileText />} color="text-amber-600 bg-amber-50" />
        <StatCard title="Approved" value={stats?.approvedApplications || 0} icon={<FiCheckCircle />} color="text-emerald-600 bg-emerald-50" />
        <StatCard title="Total Commission" value={`₹${(stats?.totalCommission || 0).toLocaleString('en-IN')}`} icon={<FiDollarSign />} color="text-violet-600 bg-violet-50" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        <div className="card">
          <h3 className="font-semibold text-slate-800 mb-4">Applications by Loan Type</h3>
          {pieData.length > 0 ? (
            <ResponsiveContainer width="100%" height={200}>
              <PieChart><Pie data={pieData} cx="50%" cy="50%" outerRadius={80} dataKey="value" label={({ name }) => name?.split(' ')[0]}>
                {pieData.map((_, i) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}
              </Pie><Tooltip /></PieChart>
            </ResponsiveContainer>
          ) : <EmptyState title="No applications yet" description="Submit your first loan application to see stats here." action={<button className="btn-primary text-sm" onClick={() => navigate('/connector/applications/new')}>Apply Now</button>} />}
        </div>
        <div className="card">
          <h3 className="font-semibold text-slate-800 mb-4">Quick Stats</h3>
          <div className="space-y-3">
            <div className="flex justify-between py-2 border-b"><span className="text-slate-500 text-sm">Connected Companies</span><span className="font-semibold">{stats?.connectedCompanies || 0}</span></div>
            <div className="flex justify-between py-2 border-b"><span className="text-slate-500 text-sm">This Month Commission</span><span className="font-semibold text-emerald-600">₹{(stats?.monthCommission || 0).toLocaleString('en-IN')}</span></div>
          </div>
          <div className="mt-4 p-3 bg-primary-50 rounded-lg">
            <p className="text-sm text-primary font-medium">💡 Tip: Connect with more DSA companies to access more banks and loan products.</p>
          </div>
        </div>
      </div>
    </div>
  );
}

export function ConnectorCompanies() {
  const [companies, setCompanies] = useState<any[]>([]);
  const [sentRequests, setSentRequests] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  const load = async () => {
    setLoading(true);
    try {
      const [compRes, reqRes] = await Promise.all([listAPI.getCompanies(), joinAPI.getSent()]);
      setCompanies(compRes.data);
      setSentRequests(reqRes.data);
    } finally { setLoading(false); }
  };
  useEffect(() => { load(); }, []);

  const getRequestStatus = (companyId: string) => sentRequests.find(r => r.toCompanyId?._id === companyId || r.toCompanyId === companyId)?.status;

  const sendRequest = async (companyId: string) => {
    try { await joinAPI.send(companyId); toast.success('Join request sent!'); load(); }
    catch (err: any) { toast.error(err?.response?.data?.message || 'Failed'); }
  };

  return (
    <div>
      <PageHeader title="DSA Companies" subtitle="Send join requests to start submitting applications" breadcrumbs={['Connector', 'Companies']} />
      {loading ? <LoadingSpinner /> : companies.length === 0 ? <EmptyState title="No companies found" /> : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {companies.map((c: any) => {
            const status = getRequestStatus(c._id);
            return (
              <div key={c._id} className="card">
                <div className="flex items-start justify-between mb-3">
                  <div className="w-10 h-10 rounded-lg bg-primary-50 flex items-center justify-center text-primary font-bold">{c.companyName?.charAt(0)}</div>
                  {status && <StatusBadge status={status} />}
                </div>
                <h3 className="font-bold text-slate-800">{c.companyName}</h3>
                <p className="text-sm text-slate-500 mt-0.5">{c.city || 'India'} · {c.email}</p>
                <div className="flex gap-4 text-sm text-slate-500 mt-3">
                  <span>{c.bankingRelations?.filter((r: any) => r.status === 'approved').length || 0} Banks</span>
                  <span>{c.connectorRelations?.filter((r: any) => r.status === 'approved').length || 0} Connectors</span>
                </div>
                <div className="mt-4">
                  {status === 'approved' ? (
                    <div className="text-emerald-600 text-sm font-medium flex items-center gap-1"><FiCheckCircle /> Connected</div>
                  ) : status === 'pending' ? (
                    <div className="text-amber-600 text-sm font-medium">Request Pending...</div>
                  ) : (
                    <button onClick={() => sendRequest(c._id)} className="btn-primary text-sm w-full flex items-center justify-center gap-2"><FiSend /> Send Join Request</button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

