export function ConnectorCommissions() {
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  useEffect(() => { commissionAPI.getAll().then(r => setData(r.data)).finally(() => setLoading(false)); }, []);
  return (
    <div>
      <PageHeader title="My Commissions" breadcrumbs={['Connector', 'Commissions']} />
      {loading ? <LoadingSpinner /> : (
        <>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
            <StatCard title="Total Earned" value={`₹${(data?.total || 0).toLocaleString('en-IN')}`} icon={<FiDollarSign />} color="text-emerald-600 bg-emerald-50" />
            <StatCard title="Paid" value={`₹${(data?.commissions?.filter((c: any) => c.status === 'paid').reduce((s: number, c: any) => s + c.commissionAmount, 0) || 0).toLocaleString('en-IN')}`} icon={<FiCheckCircle />} color="text-blue-600 bg-blue-50" />
            <StatCard title="Pending" value={`₹${(data?.commissions?.filter((c: any) => c.status === 'pending').reduce((s: number, c: any) => s + c.commissionAmount, 0) || 0).toLocaleString('en-IN')}`} icon={<FiFileText />} color="text-amber-600 bg-amber-50" />
          </div>
          <div className="card">
            {!data?.commissions?.length ? <EmptyState title="No commissions yet" description="Commissions are credited when loans are disbursed." /> : (
              <table className="w-full">
                <thead className="bg-slate-50"><tr><th className="table-th">App ID</th><th className="table-th">Loan Type</th><th className="table-th">Loan Amount</th><th className="table-th">Rate</th><th className="table-th">Commission</th><th className="table-th">Status</th><th className="table-th">Date</th></tr></thead>
                <tbody>
                  {data.commissions.map((c: any) => (
                    <tr key={c._id} className="table-row">
                      <td className="table-td font-mono text-xs text-primary">{c.applicationId?.applicationId}</td>
                      <td className="table-td text-sm">{c.loanType}</td>
                      <td className="table-td">₹{(c.loanAmount || 0).toLocaleString('en-IN')}</td>
                      <td className="table-td">{c.commissionRate}%</td>
                      <td className="table-td font-semibold text-emerald-600">₹{(c.commissionAmount || 0).toLocaleString('en-IN')}</td>
                      <td className="table-td"><StatusBadge status={c.status} /></td>
                      <td className="table-td text-xs">{new Date(c.createdAt).toLocaleDateString('en-IN')}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </>
      )}
    </div>
  );
}

