export function ConnectorNotifications() {
  const [notifs, setNotifs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [detail, setDetail] = useState<any>(null);
  const [detailLoading, setDetailLoading] = useState(false);

  // ---- NEW: search / filter / pagination state ----
  const [searchInput, setSearchInput] = useState('');   // raw text box value
  const [search, setSearch] = useState('');              // debounced value actually sent to API
  const [filter, setFilter] = useState<'all' | 'unread' | 'read'>('all');
  const [page, setPage] = useState(1);
  const [limit, setLimit] = useState(10);
  const [totalCount, setTotalCount] = useState(0);
  const [totalPages, setTotalPages] = useState(1);

  // Debounce the search box -> `search` (waits 400ms after typing stops)
  useEffect(() => {
    const t = setTimeout(() => {
      setSearch(searchInput.trim());
      setPage(1); // reset to first page whenever the search text changes
    }, 400);
    return () => clearTimeout(t);
  }, [searchInput]);

  // Reset to page 1 whenever filter or limit changes
  useEffect(() => {
    setPage(1);
  }, [filter, limit]);

  // ---- Main fetch ----
  useEffect(() => {
    setLoading(true);

    // ============================================================
    // BACKEND INTEGRATION POINT #1
    // ------------------------------------------------------------
    // This is the ONLY place you need to change to wire up the
    // real backend. Replace the params object below with whatever
    // your API's notifAPI.getAll() actually accepts, and read the
    // response shape below to match what your API returns.
    //
    // Suggested query params to support on the server:
    //   page      -> which page (1-based)
    //   limit     -> page size (10 / 25 / 50)
    //   search    -> free text, should match against BOTH
    //                notification title/message AND the linked
    //                Application ID (e.g. "BKL000067")
    //   status    -> 'all' | 'unread' | 'read'
    //
    // Expected response shape (adjust to match your API):
    //   {
    //     notifications: [...],
    //     total: 137,          // total matching rows (for pagination)
    //     totalPages: 14        // or compute as Math.ceil(total/limit)
    //   }
    // ============================================================
    notifAPI
      .getAll({ page, limit, search, status: filter })
      .then((r) => {
        setNotifs(r.data.notifications);
        // BACKEND INTEGRATION POINT #2: map these to your actual response fields
        setTotalCount(r.data.total ?? r.data.notifications.length);
       setTotalPages(r.data.pages ?? Math.max(1, Math.ceil((r.data.total ?? r.data.notifications.length) / limit)));
      })
      .finally(() => setLoading(false));
  }, [page, limit, search, filter]);

  const markRead = async (id: string) => {
    await notifAPI.markRead(id);
    setNotifs((p) => p.map((n) => (n._id === id ? { ...n, isRead: true } : n)));
  };

  const viewDetail = async (e: React.MouseEvent, n: any) => {
    e.stopPropagation();
    if (!n.relatedId) return;
    setDetail({ open: true, data: null, title: n.title });
    setDetailLoading(true);
    try {
      const res = await appAPI.getNotificationDetail(n.relatedId);
      setDetail({ open: true, data: res.data, title: n.title });
    } catch {
      setDetail({ open: true, data: null, title: n.title, error: true });
    } finally {
      setDetailLoading(false);
    }
  };

  const startRow = totalCount === 0 ? 0 : (page - 1) * limit + 1;
  const endRow = Math.min(page * limit, totalCount);

  return (
    <div>
      <PageHeader
        title="Notifications"
        breadcrumbs={['Connector', 'Notifications']}
        actions={
          <button
            className="btn-secondary text-sm w-full sm:w-auto"
            onClick={async () => {
              await notifAPI.markAllRead();
              setNotifs((p) => p.map((n) => ({ ...n, isRead: true })));
            }}
          >
            Mark all read
          </button>
        }
      />

      {/* ---- NEW: search + filter bar ---- */}
      <div className="flex flex-col sm:flex-row gap-2 sm:items-center sm:justify-between mb-3">
        <div className="relative flex-1 max-w-sm">
          <FiSearch className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
          <input
            type="text"
            value={searchInput}
            onChange={(e) => setSearchInput(e.target.value)}
            placeholder="Search by name or Application ID (e.g. BKL000067)"
            className="w-full pl-9 pr-3 py-2 text-sm border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary/30"
          />
        </div>

        <div className="flex items-center gap-2">
          <select
            value={filter}
            onChange={(e) => setFilter(e.target.value as any)}
            className="text-sm border border-slate-200 rounded-lg px-2 py-2 focus:outline-none focus:ring-2 focus:ring-primary/30"
          >
            <option value="all">All</option>
            <option value="unread">Unread</option>
            <option value="read">Read</option>
          </select>

          <select
            value={limit}
            onChange={(e) => setLimit(Number(e.target.value))}
            className="text-sm border border-slate-200 rounded-lg px-2 py-2 focus:outline-none focus:ring-2 focus:ring-primary/30"
          >
            <option value={10}>10 / page</option>
            <option value={25}>25 / page</option>
            <option value={50}>50 / page</option>
          </select>
        </div>
      </div>

      <div className="card !p-0 sm:!p-4 overflow-hidden">
        {loading ? (
          <LoadingSpinner />
        ) : notifs.length === 0 ? (
          <EmptyState title="No notifications" />
        ) : (
          <div className="divide-y divide-slate-100">
            {notifs.map((n) => (
              <div
                key={n._id}
                onClick={() => !n.isRead && markRead(n._id)}
                className={`py-3 px-3 sm:px-2 flex flex-col sm:flex-row sm:items-start sm:justify-between gap-1.5 sm:gap-3 cursor-pointer hover:bg-slate-50 ${
                  !n.isRead ? 'bg-blue-50' : ''
                }`}
              >
                <div className="flex-1 min-w-0">
                  <div className="flex items-start justify-between gap-2">
                    <p className="font-medium text-sm text-slate-800 break-words">{n.title}</p>
                    {n.relatedId && (
                      <button
                        onClick={(e) => viewDetail(e, n)}
                        className="text-slate-400 hover:text-primary shrink-0 sm:hidden"
                        title="View full details"
                      >
                        <FiEye size={16} />
                      </button>
                    )}
                  </div>
                  <p className="text-sm text-slate-600 mt-0.5 break-words">{n.message}</p>
                  <span className="text-xs text-slate-400 mt-1 block sm:hidden">
                    {new Date(n.createdAt).toLocaleString('en-IN')}
                  </span>
                </div>
                <div className="hidden sm:flex items-start gap-2 shrink-0">
                  <span className="text-xs text-slate-400 whitespace-nowrap">
                    {new Date(n.createdAt).toLocaleString('en-IN')}
                  </span>
                  {n.relatedId && (
                    <button
                      onClick={(e) => viewDetail(e, n)}
                      className="text-slate-400 hover:text-primary mt-0.5"
                      title="View full details"
                    >
                      <FiEye size={16} />
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}

        {/* ---- NEW: pagination footer ---- */}
        {!loading && notifs.length > 0 && (
          <div className="flex items-center justify-between px-3 py-3 border-t border-slate-100 text-sm text-slate-500">
            <span>
              Showing {startRow}-{endRow} of {totalCount}
            </span>
            <div className="flex items-center gap-2">
              <button
                disabled={page <= 1}
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                className="p-1.5 rounded-lg border border-slate-200 disabled:opacity-40 disabled:cursor-not-allowed hover:bg-slate-50"
              >
                <FiChevronLeft size={16} />
              </button>
              <span className="text-slate-700 font-medium">
                {page} / {totalPages}
              </span>
              <button
                disabled={page >= totalPages}
                onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                className="p-1.5 rounded-lg border border-slate-200 disabled:opacity-40 disabled:cursor-not-allowed hover:bg-slate-50"
              >
                <FiChevronRight size={16} />
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Detail Popup */}
      {detail?.open && (
        <div className="fixed inset-0 bg-black/40 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="bg-white rounded-t-xl sm:rounded-xl shadow-xl w-full max-w-lg max-h-[85vh] sm:max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between p-4 border-b sticky top-0 bg-white">
              <h3 className="font-semibold text-slate-800 text-sm sm:text-base pr-2 break-words">{detail.title}</h3>
              <button onClick={() => setDetail(null)} className="text-slate-400 hover:text-slate-600 text-xl leading-none shrink-0">
                ✕
              </button>
            </div>
            <div className="p-4">
              {detailLoading ? (
                <LoadingSpinner />
              ) : detail.error ? (
                <p className="text-red-500 text-sm">Could not load details.</p>
              ) : detail.data ? (
                <div className="space-y-3 text-sm">
                  {/* App Info */}
                  <div className="grid grid-cols-2 gap-2 bg-slate-50 rounded-lg p-3">
                    <div>
                      <p className="text-slate-400 text-xs">Application ID</p>
                      <p className="font-mono font-bold text-primary">{detail.data.applicationId}</p>
                    </div>
                    <div>
                      <p className="text-slate-400 text-xs">Loan Type</p>
                      <p className="font-semibold">{detail.data.loanType}</p>
                    </div>
                    <div>
                      <p className="text-slate-400 text-xs">Amount</p>
                      <p className="font-semibold">₹{(detail.data.loanAmount || 0).toLocaleString('en-IN')}</p>
                    </div>
                    <div>
                      <p className="text-slate-400 text-xs">Applicant</p>
                      <p className="font-semibold">{detail.data.applicantName}</p>
                    </div>
                  </div>
                  {/* Bank Responses */}
                  <p className="font-semibold text-slate-700">Bank Responses</p>
                  {detail.data.bankAssignments?.map((ba: any, i: number) => (
                    <div key={i} className="border rounded-lg p-3 space-y-1">
                      <p className="font-semibold text-slate-800">{ba.bankName}</p>
                      {ba.interestStatus && ba.interestStatus !== 'pending' && (
                        <p>
                          <span className="text-slate-400">Interest: </span>
                          <span
                            className={
                              ba.interestStatus === 'interested'
                                ? 'text-emerald-600 font-semibold'
                                : ba.interestStatus === 'not_interested'
                                ? 'text-red-600 font-semibold'
                                : 'text-amber-600 font-semibold'
                            }
                          >
                            {ba.interestStatus.replace(/_/g, ' ').toUpperCase()}
                          </span>
                        </p>
                      )}
                      {ba.interestNote && (
                        <p>
                          <span className="text-slate-400">Note: </span>
                          {ba.interestNote}
                        </p>
                      )}
                      {ba.rejectionReason && (
                        <p>
                          <span className="text-slate-400">Rejection Reason: </span>
                          <span className="text-red-600 font-medium">{ba.rejectionReason}</span>
                        </p>
                      )}
                      {ba.sanctionAmount && (
                        <p>
                          <span className="text-slate-400">Sanction Amount: </span>₹
                          {Number(ba.sanctionAmount).toLocaleString('en-IN')}
                        </p>
                      )}
                      {ba.disbursementAmount && (
                        <p>
                          <span className="text-slate-400">Disbursed: </span>₹
                          {Number(ba.disbursementAmount).toLocaleString('en-IN')}
                        </p>
                      )}
                      <p>
                        <span className="text-slate-400">Status: </span>
                        {ba.status}
                      </p>
                    </div>
                  ))}
                </div>
              ) : null}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}


export function ConnectorProfile() {
  const { user } = useAuth();
  const [form, setForm] = useState({ name: user?.name || '', mobile: user?.mobile || '', email: user?.email || '' });
  const [pwForm, setPwForm] = useState({ currentPassword: '', newPassword: '' });
  // authAPI imported above
  return (
    <div>
      <PageHeader title="My Profile" breadcrumbs={['Connector', 'Profile']} />
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="card">
          <h3 className="font-semibold text-slate-800 mb-4">Personal Information</h3>
          <div className="space-y-4">
            <div><label className="label">Full Name</label><input className="input" value={form.name} onChange={e => setForm(p => ({ ...p, name: e.target.value }))} /></div>
            <div><label className="label">Email</label><input className="input" type="email" value={form.email} disabled readOnly style={{ backgroundColor: "#f8fafc" }} /></div>
            <div><label className="label">Mobile</label><input className="input" value={form.mobile} onChange={e => setForm(p => ({ ...p, mobile: e.target.value }))} /></div>
            <button className="btn-primary" onClick={() => toast.success('Profile updated')}>Save Changes</button>
          </div>
        </div>
        <div className="card">
          <h3 className="font-semibold text-slate-800 mb-4">Change Password</h3>
          <div className="space-y-4">
            <div><label className="label">Current Password</label><input className="input" type="password" value={pwForm.currentPassword} onChange={e => setPwForm(p => ({ ...p, currentPassword: e.target.value }))} /></div>
            <div><label className="label">New Password</label><input className="input" type="password" value={pwForm.newPassword} onChange={e => setPwForm(p => ({ ...p, newPassword: e.target.value }))} /></div>
            <button className="btn-primary" onClick={async () => { try { await authAPI.changePassword(pwForm); toast.success('Password changed'); setPwForm({ currentPassword: '', newPassword: '' }); } catch { toast.error('Failed'); } }}>Update Password</button>
          </div>
        </div>
      </div>
    </div>
  );
}











