export const LoanTypeDropdown: React.FC<{ value: string; onChange: (v: string) => void; options: readonly string[]; placeholder?: string }> = ({ value, onChange, options, placeholder = 'All Loan Types' }) => {
  const [open, setOpen] = React.useState(false);
  const ref = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const close = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', close);
    return () => document.removeEventListener('mousedown', close);
  }, []);

  return (
    <div className="relative w-full sm:w-64" ref={ref}>
      <button
        type="button"
        className="input w-full text-left flex items-center justify-between"
        onClick={() => setOpen(o => !o)}
      >
        <span className="truncate">{value || placeholder}</span>
        <span className="text-slate-400 ml-2 flex-shrink-0">▾</span>
      </button>

      {open && (
        // <div className="absolute z-20 mt-1 w-full max-h-64 overflow-y-auto bg-white border border-slate-200 rounded-lg shadow-lg">
        // h-4/7
        <div className="absolute z-20 mt-1 w-full max-w-[calc(100vw-2rem)] max-h-64 overflow-y-auto bg-white border border-slate-200 rounded-lg shadow-lg"> 
        
        
        <div
            className="px-4 py-2.5 text-sm hover:bg-slate-50 cursor-pointer"
            onClick={() => { onChange(''); setOpen(false); }}
          >
            {placeholder}
          </div>
          {options.map(opt => (
            <div
              key={opt}
              className="px-4 py-2.5 text-sm hover:bg-slate-50 cursor-pointer"
              onClick={() => { onChange(opt); setOpen(false); }}
            >
              {opt}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};


export const StatusBadge: React.FC<{ status: string }> = ({ status }) => {
  const stage = LOAN_STAGES.find(s => s.key === status);
  const colorMap: Record<string, string> = {
    active: 'badge-green', blocked: 'badge-red', spam: 'badge-red', inactive: 'badge-gray',
    pending: 'badge-yellow', approved: 'badge-green', rejected: 'badge-red',
  };
  const cls = stage?.color || colorMap[status] || 'badge-gray';
  const label = stage?.label || status?.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase()) || '—';
  return <span className={cls}>{label}</span>;
};

export const LoadingSpinner: React.FC<{ size?: string; fullPage?: boolean }> = ({ size = 'h-8 w-8', fullPage }) => {
  const spinner = <div className={`${size} border-4 border-primary/20 border-t-primary rounded-full animate-spin`} />;
  if (fullPage) return <div className="flex items-center justify-center min-h-[400px]">{spinner}</div>;
  return <div className="flex items-center justify-center p-8">{spinner}</div>;
};

