export const ConfirmModal: React.FC<{ open: boolean; title: string; message: string; onConfirm: () => void; onCancel: () => void; danger?: boolean; loading?: boolean }> = ({ open, title, message, onConfirm, onCancel, danger, loading }) => {
  if (!open) return null;
  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl max-w-md w-full p-6 shadow-2xl">
        <div className={`w-12 h-12 rounded-full flex items-center justify-center mb-4 ${danger ? 'bg-red-100' : 'bg-blue-100'}`}>
          <FiAlertCircle className={`text-xl ${danger ? 'text-red-600' : 'text-blue-600'}`} />
        </div>
        <h3 className="text-lg font-semibold text-slate-800 mb-2">{title}</h3>
        <p className="text-slate-600 text-sm mb-6">{message}</p>
        <div className="flex gap-3 justify-end">
          <button className="btn-secondary" onClick={onCancel} disabled={loading}>Cancel</button>
          <button className={danger ? 'btn-danger' : 'btn-primary'} onClick={onConfirm} disabled={loading}>
            {loading ? <FiLoader className="animate-spin mx-2" /> : 'Confirm'}
          </button>
        </div>
      </div>
    </div>
  );
};

