export const FileUpload: React.FC<{ label?: string; onChange: (f: File | File[]) => void; multiple?: boolean; accept?: string; required?: boolean }> = ({ label, onChange, multiple, accept = '.pdf,.jpg,.jpeg,.png', required }) => {
  const ref = React.useRef<HTMLInputElement>(null);
  return (
    <div>
      {label && <label className="label">{label}{required && <span className="text-red-500 ml-1">*</span>}</label>}
      <div onClick={() => ref.current?.click()} className="border-2 border-dashed border-slate-300 rounded-lg p-6 text-center cursor-pointer hover:border-primary hover:bg-primary-50 transition-colors">
        <div className="text-slate-400 text-3xl mb-2">📎</div>
        <p className="text-sm text-slate-600">Click to upload {multiple ? 'files' : 'a file'}</p>
        <p className="text-xs text-slate-400 mt-1">PDF, JPG, PNG up to 10MB</p>
      </div>
      <input ref={ref} type="file" className="hidden" multiple={multiple} accept={accept}
        onChange={e => { const f = e.target.files; if (f) onChange(multiple ? Array.from(f) : f[0]); }} />
    </div>
  );
};

