export const QueryThread: React.FC<{ queries: any[]; onReply?: (queryId: string, answer: string) => void; canReply?: boolean }> = ({ queries, onReply, canReply }) => {
  const [answers, setAnswers] = React.useState<Record<string, string>>({});
  if (!queries?.length) return <p className="text-sm text-slate-400">No queries raised.</p>;
  return (
    <div className="space-y-4">
      {queries.map((q: any) => (
        <div key={q._id} className="border border-slate-200 rounded-lg p-4">
          <div className="flex items-start justify-between mb-2">
            <span className="text-sm font-medium text-slate-700">{q.raisedByName}</span>
            <StatusBadge status={q.status} />
          </div>
          <p className="text-sm text-slate-800 bg-slate-50 rounded p-2 mb-2">❓ {q.question}</p>
          {q.answer ? (
            <p className="text-sm text-emerald-700 bg-emerald-50 rounded p-2">✅ {q.answer}</p>
          ) : canReply ? (
            <div className="flex gap-2 mt-2">
              <input className="input flex-1 text-xs" placeholder="Type your reply..." value={answers[q._id] || ''} onChange={e => setAnswers(p => ({ ...p, [q._id]: e.target.value }))} />
              <button className="btn-primary text-xs px-3 py-1.5" onClick={() => { if (answers[q._id] && onReply) { onReply(q._id, answers[q._id]); setAnswers(p => ({ ...p, [q._id]: '' })); } }}>Reply</button>
            </div>
          ) : <p className="text-xs text-slate-400 italic">Awaiting response...</p>}
        </div>
      ))}
    </div>
  );
};

export default {};
